sample:
# lesson02 ch03: 参照のチェーン
# base → middle → last の順で自動的に作られます。

resource "terraform_data" "base" {
  input = "base-v1"
}

resource "terraform_data" "middle" {
  # base への参照。base が先に作られます
  input = terraform_data.base.output
}

resource "terraform_data" "last" {
  # middle への参照。チェーンは何段でも OK
  input = terraform_data.middle.output
}

output "chain_result" {
  value = terraform_data.last.output
}

exercise.starter:
# network → server の順に自動で作られるように参照でつなぐ
resource "terraform_data" "network" {
}

exercise.answer:
# server の input に network の output を参照で渡すと、
# 「network を先に作る」という依存関係が自動でできます(順序指定は不要)。
resource "terraform_data" "network" {
  input = "vpc-main"
}

resource "terraform_data" "server" {
  input = terraform_data.network.output
}

output "network_name" {
  value = terraform_data.network.output
}

output "server_network" {
  value = terraform_data.server.output
}
